function c43175027.spfilter(c,e,tp)
	return c:IsAttribute(ATTRIBUTE_WATER) and c:IsLevelBelow(4) and not c:IsCode(43175027)
		and c:IsCanBeSpecialSummoned(e,0,tp,false,false)
end
